entries[12162] = { ["name"] = "Pläne: Gehärtetes Eisenkurzschwert", ["text"] = "Benötigt Schmiedekunst (160)\nBenutzen: Lehrt Euch die Herstellung eines gehärteten Eisenkurzschwerts.\nVerkaufspreis:\nGehärtetes Eisenkurzschwert\nWird beim Anlegen gebunden\nEinhändig Schwert\n31 - 59 Schaden Tempo 2.70\n(16.67 Schaden pro Sekunde)\n+ 10 Angriffskraft.\nHaltbarkeit 75 / 75\nBenötigt Stufe 27\nVerkaufspreis:\nBenötigt Eisenbarren (6), Starker Fluxus (2), Schwerer Schleifstein , Geringer Mondstein (2), Schweres Leder (3)" }
